<?php
function bodyJson($max=1500000){$raw=file_get_contents('php://input');if(strlen($raw)>$max)throw new Exception('Request too large.');$v=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(!is_array($v))throw new Exception('Invalid request.');return $v;}
function cmsApi(){requireAdmin();if($_SERVER['REQUEST_METHOD']==='GET')jsonResponse(allContent(true));requireOrigin();$v=bodyJson();if(in_array($v['action']??'',['delete','restore'],true)){require_once __DIR__.'/content-trash.php';contentTrash($v);}if(($v['action']??'')==='settings'){$s=$v['value']??null;if(!is_array($s))throw new Exception('Invalid settings.');foreach($s as $x)if(!is_string($x)||strlen($x)>20000)throw new Exception('Invalid setting.');if(!empty($s['seoOrigin'])&&$s['seoOrigin']!==SITE_ORIGIN)throw new Exception('Use https://besttoursdubai.com for this website.');$s['address']='khalid bin waleed road raviz center point hotel, Dubai, United Arab Emirates';$s['address2']='';save('settings',$s);jsonResponse(['ok'=>true,'settings'=>$s]);}
if(($v['action']??'')==='seo_patch'){
 $path=$v['path']??null;$changes=$v['value']??null;
 if(!is_string($path)||!is_array($changes)||array_diff(array_keys($changes),['title','contentHtml','seo','summary']))throw new Exception('Invalid SEO update.');
 $current=null;foreach(allContent(true)['pages'] as $candidate)if($candidate['path']===$path){$current=$candidate;break;}
 if(!$current||!empty($current['deletedAt']))throw new Exception('Choose published or draft content outside Trash.');
 foreach(['title','contentHtml','seo'] as $key)if(array_key_exists($key,$changes))$current[$key]=$changes[$key];
 if(array_key_exists('summary',$changes))$current['experience']['summary']=$changes['summary'];
 $v=['action'=>'page','value'=>$current];
}
if(($v['action']??'')!=='page')throw new Exception('Invalid action.');$p=$v['value']??null;if(!is_array($p)||!preg_match('~^/[a-z0-9_./-]*$~',$p['path']??'')||str_contains($p['path'],'..')||preg_match('~^/(api|dashboard|media|uploads|auth|signout|signin)~',$p['path'])||!in_array($p['type']??'',['tour','attraction','guide','page'])||!in_array($p['status']??'',['published','draft'])||!is_string($p['title']??null)||!trim($p['title'])||strlen($p['title'])>300)throw new Exception('Check the page title and URL.');
$seo=array_merge(['title'=>'','description'=>'','keywords'=>'','slug'=>'','noindex'=>false,'socialImage'=>''],$p['seo']??[]);foreach(['title','description','keywords','slug','socialImage'] as $key)if(!is_string($seo[$key])||strlen($seo[$key])>($key==='keywords'?5000:1000))throw new Exception('Check the SEO fields.');if($seo['slug']&&!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$seo['slug']))throw new Exception('Use lowercase words separated by hyphens for the URL slug.');if($seo['socialImage']&&!validImage($seo['socialImage']))throw new Exception('Invalid social image URL.');$p['seo']=$seo;$canonical=publicPath($p);if(preg_match('~^/(api|dashboard|media|uploads|auth|assets|optimized|signin|signout)(/|$)~',$canonical)||in_array($canonical,['/booking.php','/search.php','/thank-you','/robots.txt','/sitemap.xml','/sitemap-index.xml','/sitemaps/pages.xml','/sitemaps/tours.xml','/sitemaps/attractions.xml','/sitemaps/guides.xml']))throw new Exception('That URL is reserved.');
$previous=null;foreach(allContent(true)['pages'] as $old){if($old['path']===$p['path']){$previous=$old;continue;}if(in_array($canonical,array_merge([$old['path'],publicPath($old)],$old['aliases']??[])))throw new Exception('That URL is already in use.');}
if(!empty($previous['deletedAt']))throw new Exception('Restore this content from Trash before editing it.');unset($p['deletedAt']);
$ex=$p['experience']??null;if(!is_array($ex))throw new Exception('Invalid experience information.');foreach(['price','discountPrice'] as $key)if($ex[$key]!==null&&(!is_numeric($ex[$key])||$ex[$key]<0||$ex[$key]>10000000))throw new Exception('Check the prices.');if($ex['discountPrice']!==null&&($ex['price']===null||$ex['discountPrice']>$ex['price']))throw new Exception('Discounted price must not exceed regular price.');if(!is_int($ex['ticketCount'])||$ex['ticketCount']<1||$ex['ticketCount']>10000)throw new Exception('Invalid ticket option count.');foreach(['summary','location','duration','departure','returnTime','transfer','minimumAge'] as $key)if(!is_string($ex[$key])||strlen($ex[$key])>20000)throw new Exception('Invalid experience information.');foreach($ex['packages'] as $pkg){if(!trim($pkg['name'])||!in_array($pkg['mode'],['per_person','per_unit','per_group','per_vehicle','per_ticket','flat']))throw new Exception('Invalid package.');foreach(['adultPrice','childPrice','unitPrice','capacity'] as $k)if(!is_numeric($pkg[$k])||$pkg[$k]<0||$pkg[$k]>10000000)throw new Exception('Invalid package price.');if($pkg['mode']==='per_group'&&$pkg['capacity']<1)throw new Exception('Invalid guest capacity.');}foreach($ex['addons'] as $a)if(!trim($a['name'])||!is_numeric($a['price'])||$a['price']<0||!in_array($a['mode'],['per_unit','per_person','per_adult','per_child','flat']))throw new Exception('Invalid add-on.');
if(!is_array($p['images'])||!is_array($p['fields']))throw new Exception('Invalid content.');foreach($p['images'] as $img)if($img['src']&&!validImage($img['src']))throw new Exception('Invalid image URL.');$p['contentHtml']=cleanHtml($p['contentHtml']??'');$p['title']=trim($p['title']);$p['id']=$p['path'];$p['aliases']=array_values(array_unique(array_filter(array_merge($previous['aliases']??[],$previous&&publicPath($previous)!==$canonical?[publicPath($previous)]:[]),fn($x)=>$x!==$canonical&&$x!==$p['path'])));if(!empty($p['publishedAt'])&&strtotime($p['publishedAt'])===false)throw new Exception('Invalid publish date.');$significant=!$previous;foreach(['title','contentHtml','seo','experience','images','fields','status','publishedAt','author'] as $field)if(($p[$field]??null)!==($previous[$field]??null))$significant=true;$p['modifiedAt']=$significant?gmdate('c'):($previous['modifiedAt']??$previous['publishedAt']??null);save('page:'.$p['path'],$p);jsonResponse(['ok'=>true,'page'=>$p]);}
function bookingApi(){if($_SERVER['REQUEST_METHOD']==='GET'){requireAdmin();$rows=query("SELECT value FROM cms WHERE key LIKE 'booking:%' ORDER BY updated_at DESC LIMIT 500")->fetchAll(PDO::FETCH_COLUMN);jsonResponse(['bookings'=>array_map(fn($s)=>json_decode($s,true),$rows)]);}requireOrigin();$v=bodyJson(15000);if(in_array($v['action']??'',['status','delete'])){requireAdmin();if(!is_string($v['id']??null)||!preg_match('/^[a-f0-9-]{36}$/',$v['id']))throw new Exception('Invalid booking request.');$key='booking:'.$v['id'];if($v['action']==='delete'){$q=query('DELETE FROM cms WHERE key=?',[$key]);if(!$q->rowCount())jsonResponse(['error'=>'Request not found.'],404);jsonResponse(['ok'=>true]);}if(!in_array($v['status']??'',['pending','confirmed','cancelled']))throw new Exception('Invalid status.');require_once __DIR__.'/booking-status.php';$result=updateBookingStatus($key,$v['status']);jsonResponse($result,$result['httpStatus']??200);}
limitRequests('booking',20,3600);if(!empty($v['website']))throw new Exception('Please try again.');if(!preg_match('/^[a-f0-9-]{36}$/',$v['requestId']??''))throw new Exception('Reload the booking form.');foreach(['customerName'=>150,'customerEmail'=>254,'customerPhone'=>40,'pickupLocation'=>3000,'notes'=>3000] as $k=>$max)if(!is_string($v[$k]??null)||strlen($v[$k])>$max||(in_array($k,['customerName','customerEmail','customerPhone'])&&!trim($v[$k])))throw new Exception('Complete your contact details.');if(!filter_var($v['customerEmail'],FILTER_VALIDATE_EMAIL)||str_contains($v['customerEmail'],"\n")||str_contains($v['customerEmail'],"\r"))throw new Exception('Enter a valid email.');if(strlen(preg_replace('/\D/','',$v['customerPhone']))<7)throw new Exception('Enter a valid phone number.');$date=DateTime::createFromFormat('!Y-m-d',$v['travelDate']??'');if(!$date||$date->format('Y-m-d')!==$v['travelDate']||$v['travelDate']<(new DateTime('now',new DateTimeZone('Asia/Dubai')))->format('Y-m-d'))throw new Exception('Choose today or a future tour date.');$data=allContent();$p=null;foreach($data['pages'] as $x)if($x['path']===($v['path']??'')&&$x['status']==='published'&&in_array($x['type'],['tour','attraction'])&&empty($x['publishedAt'])||($x['path']===($v['path']??'')&&$x['status']==='published'&&in_array($x['type'],['tour','attraction'])&&strtotime($x['publishedAt'])<=time())){$p=$x;break;}if(!$p)throw new Exception('This experience is unavailable.');
$integer=function($n,$min,$max){if(filter_var($n,FILTER_VALIDATE_INT)===false||$n<$min||$n>$max)throw new Exception('Check quantities.');return (int)$n;};$adults=$integer($v['adults']??null,1,100);$children=$integer($v['children']??null,0,100);$units=$integer($v['units']??null,1,100);$packages=bookingPackages($p);$pkg=$packages[$integer($v['packageIndex']??null,0,count($packages)-1)];if(!is_array($v['addonQuantities']??null)||count($v['addonQuantities'])!==count($p['experience']['addons']))throw new Exception('Check add-ons.');$addons=[];$extras=0;foreach($p['experience']['addons'] as $i=>$a){$quantity=$integer($v['addonQuantities'][$i],0,20);if($quantity){$a['quantity']=$quantity;$addons[]=$a;$extras+=addonTotal($a,$quantity,$adults,$children);}}$subtotal=packageTotal($pkg,$adults,$children,$units);$reference='BTD-'.strtoupper(substr($v['requestId'],0,8));$b=['id'=>$v['requestId'],'reference'=>$reference,'createdAt'=>gmdate('c'),'status'=>'pending','path'=>$p['path'],'title'=>$p['title'],'customerName'=>trim($v['customerName']),'customerEmail'=>trim($v['customerEmail']),'customerPhone'=>trim($v['customerPhone']),'travelDate'=>$v['travelDate'],'adults'=>$adults,'children'=>$children,'units'=>$units,'packageName'=>$pkg['name'],'packageMode'=>$pkg['mode'],'unitLabel'=>$pkg['unitLabel'],'groups'=>$pkg['mode']==='per_group'?ceil(($adults+$children)/max(1,$pkg['capacity'])):($pkg['mode']==='flat'?1:$units),'addons'=>$addons,'pickupLocation'=>$v['pickupLocation'],'notes'=>$v['notes'],'subtotal'=>$subtotal,'extras'=>$extras,'total'=>activePrice($p)===null?null:$subtotal+$extras];
$q=query('INSERT OR IGNORE INTO cms VALUES(?,?,?)',['booking:'.$b['id'],json_encode($b),$b['createdAt']]);if($q->rowCount()){$lines=[];foreach(['Reference'=>$reference,'Experience'=>$b['title'],'Customer'=>$b['customerName'],'Email'=>$b['customerEmail'],'Phone'=>$b['customerPhone'],'Tour date'=>$b['travelDate'],'Package'=>$b['packageName'],'Adults'=>$adults,'Children'=>$children,'Units'=>$units,'Estimated total'=>$b['total']===null?'Price on request':'AED '.$b['total'],'Pickup'=>$b['pickupLocation'],'Notes'=>$b['notes'],'Add-ons'=>implode(', ',array_map(fn($a)=>$a['name'].' x '.$a['quantity'],$addons))] as $label=>$value)$lines[]=$label.': '.$value;$sent=notify('New booking request '.$reference,implode("\n",$lines)."\n\nReview this request: ".SITE_ORIGIN.'/dashboard',$b['customerEmail']);$b['notificationStatus']=$sent?'sent':'failed';save('booking:'.$b['id'],$b);}
sessionStart();$_SESSION['bookingReceipt']=['reference'=>$reference,'title'=>$p['title'],'travelDate'=>$v['travelDate'],'packageName'=>$pkg['name'],'expires'=>time()+3600];
jsonResponse(['ok'=>true,'redirectUrl'=>'/thank-you','reference'=>$reference,'whatsappUrl'=>'https://wa.me/'.preg_replace('/\D/','',$data['settings']['whatsapp']).'?text='.rawurlencode('Hello '.$data['settings']['name'].', please confirm booking request '.$reference.' for '.$p['title'].' on '.$v['travelDate'].'.')]);}
function uploadApi(){requireAdmin();requireOrigin();$f=$_FILES['file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>8000000)throw new Exception('Choose an image under 8 MB.');$meta=getimagesize($f['tmp_name']);if(!$meta||!in_array($meta['mime'],['image/png','image/jpeg','image/webp','image/gif']))throw new Exception('Choose a PNG, JPEG, WebP or GIF image.');$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp','image/gif'=>'gif'][$meta['mime']];$name=substr(trim(preg_replace('/[^a-z0-9]+/','-',strtolower($_POST['name']??'image')),'-'),0,100).'-'.bin2hex(random_bytes(8)).'.'.$ext;$folder=PUBLIC_DIR.'/uploads';if(!is_dir($folder))mkdir($folder,0755,true);if(!move_uploaded_file($f['tmp_name'],$folder.'/'.$name))throw new Exception('Upload failed.');jsonResponse(['url'=>'/uploads/'.$name,'width'=>$meta[0],'height'=>$meta[1]]);}
